import{_ as u,C as o,o as w,c as g,j as t,a,E as s,a8 as m}from"./chunks/framework.27XeWUA0.js";const n="/schedule-dashboard/thumbs/yt/UGuNt2_Oz8s-640.webp",b="/schedule-dashboard/thumbs/yt/UGuNt2_Oz8s-1280.webp",r="/schedule-dashboard/thumbs/yt/kRJjSOYqW0I-640.webp",v="/schedule-dashboard/thumbs/yt/kRJjSOYqW0I-1280.webp",i="/schedule-dashboard/thumbs/yt/4UtrRVtUN_g-640.webp",f="/schedule-dashboard/thumbs/yt/4UtrRVtUN_g-1280.webp",l="/schedule-dashboard/thumbs/yt/Y_p3y6zP5QE-640.webp",y="/schedule-dashboard/thumbs/yt/Y_p3y6zP5QE-1280.webp",h="/schedule-dashboard/thumbs/yt/OmyqelTwpOo-640.webp",k="/schedule-dashboard/thumbs/yt/OmyqelTwpOo-1280.webp",c="/schedule-dashboard/thumbs/yt/wbRaBUhkVhc-640.webp",_="/schedule-dashboard/thumbs/yt/wbRaBUhkVhc-1280.webp",V=JSON.parse('{"title":"AI Digest · Tue 27 Oct 2026","description":"","frontmatter":{"aside":false,"outline":false},"headers":[],"params":{"date":"2026-10-27","routine":"digest"},"relativePath":"digest/2026-10-27.md","filePath":"digest/[date].md"}'),q={name:"digest/2026-10-27.md"},O=n+" 640w, "+b+" 1280w",A=r+" 640w, "+v+" 1280w",I=i+" 640w, "+f+" 1280w",x=l+" 640w, "+y+" 1280w",S=h+" 640w, "+k+" 1280w",R=c+" 640w, "+_+" 1280w",T={id:"ai-digest-·-tue-27-oct-2026",tabindex:"-1"};function U(G,e,N,P,z,C){const p=o("Badge"),d=o("DayFilter");return w(),g("div",null,[t("h1",T,[e[0]||(e[0]=a("AI Digest · Tue 27 Oct 2026 ",-1)),s(p,{type:"tip",text:"6"}),e[1]||(e[1]=a()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#ai-digest-·-tue-27-oct-2026","aria-label":'Permalink to "AI Digest · Tue 27 Oct 2026 <Badge type="tip" text="6" />"'},"​",-1))]),e[3]||(e[3]=t("p",{class:"sub"},"AI Engineer + Better Stack daily digest — 27 Oct 2026 · run date Tue 27 Oct 2026 · 6 videos",-1)),e[4]||(e[4]=t("div",{class:"overview"},[t("p",null,[t("strong",null,"AI Engineer:"),a(" 5 new talks in the last 24 hours, all with full transcripts. The freshest are two Arize AI talks: Fuad Ali's self-improving agents demo (4:30 AM IST), which reruns his 11 Oct workshop and is a skip, and Xander Song's Harbor walkthrough (12:30 AM IST), the one worth watching today as the first proper explainer of that agent-testing framework. Greptile's build-your-own code review agent talk is a skim with concrete cost and model-routing numbers, Google DeepMind's Gemini Managed Agents talk mostly repeats Anthropic's managed-agents series, and LiveKit's voice-agent talk is a near-rerun of Jesse Hall's 11 Oct talk.")]),t("p",null,[t("strong",null,"Better Stack:"),a(" 1 new video (26 Oct, 9:15 AM IST, with transcript), a fun non-AI backtest treating the companies in HBO's "),t("em",null,"Silicon Valley"),a(" intro as an index fund; it's new ground and a quick skim.")])],-1)),s(d),e[5]||(e[5]=m('<div class="grid cards2"><article class="it full" id="v-UGuNt2_Oz8s" data-title="Agents That Self Improve While You Sleep - Fuad Ali, Arize AI" data-channel="AI Engineer" data-verdict="skip"><a class="th" href="https://www.youtube.com/watch?v=UGuNt2_Oz8s" target="_blank" rel="noopener"><img src="'+n+'" srcset="'+O+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skip">skip</span><h3><a href="https://www.youtube.com/watch?v=UGuNt2_Oz8s" target="_blank" rel="noopener">Agents That Self Improve While You Sleep - Fuad Ali, Arize AI</a></h3><div class="meta">AI Engineer · Fuad Ali, product manager, Arize AI · uploaded 27 Oct, 4:30 AM IST · 53:05</div><div class="verdict v-skip"><b>Verdict:</b> skip — it&#39;s the same Wonder Toys + Signal demo as his 11 Oct workshop and yesterday&#39;s Aparna Dhinakaran talk; if anything, skim 40:23–45:13 for the qualitative-eval Q&amp;A.</div><div class="repeat">🔁 Repeat: &#39;self-improving agents&#39; — seen 15 times before (incl. his own &quot;Building Self-Learning Loops&quot; workshop on the same Wonder Toys demo and Aparna Dhinakaran&#39;s Signal talk yesterday). New here: the planted bug is now a category-casing filter, and the loop adds &quot;living fixture&quot; datasets plus one-click evals from a Signal issue.</div><div class="repeat">🔁 Repeat: &#39;evals for agents&#39; — seen 41 times before. New here: retiring evals once they pass almost always, and an ROI argument for fixtures in CI plus sampled evals on production.</div><div class="repeat">🔁 Repeat: &#39;agent observability&#39; — seen 23 times before. New here: nothing much; a standard trace-tree walkthrough with the AX CLI&#39;s auto-instrumentation.</div><div class="repeat">🔁 Repeat: &#39;human-in-the-loop review&#39; — seen 17 times before. New here: sending low-confidence decision-model scores to annotation queues automatically (spam test: 4.6% routed to people, 99.5% accuracy on the rest).</div><div class="repeat">🔁 Repeat: &#39;always-on agents&#39; — seen 7 times before. New here: Agent Studio, for building your own Signal-style agents with skills like GitHub or DataDog on Codex, Cursor, Claude Code or OpenCode.</div><div class="repeat">🔁 Repeat: &#39;decision models&#39; — seen 4 times before. New here: he&#39;s most excited about using their low latency to route requests while the agent is running, and for multimodal evals.</div><div class="sh">The loop and the planted bug</div><ul><li><strong>Five-box maturity curve:</strong> Tracing, evals, someone reading traces, saving failures as tests, and proving the fix. Arize&#39;s flow runs trace → Signal → failure dataset → proposed eval → fix → experiment, and then a human reviews and merges (repeat) (<a href="https://www.youtube.com/watch?v=UGuNt2_Oz8s&amp;t=348s" target="_blank" rel="noopener">5:48</a>–<a href="https://www.youtube.com/watch?v=UGuNt2_Oz8s&amp;t=497s" target="_blank" rel="noopener">8:17</a>)</li><li><strong>Signal finds the bug:</strong> By default Signal reads a project&#39;s traces every 6 hours and clusters issues. On Wonder Toys it flagged redundant search retries (three sequential LLM calls). Its coding agent worked for 6 minutes and found the root cause: categories are stored as lowercase hyphenated slugs while the LLM passes title-case names, so &quot;car games&quot; returns nothing, the agent searches every product, and latency hits 14–17 seconds (repeat) (<a href="https://www.youtube.com/watch?v=UGuNt2_Oz8s&amp;t=735s" target="_blank" rel="noopener">12:15</a>–<a href="https://www.youtube.com/watch?v=UGuNt2_Oz8s&amp;t=955s" target="_blank" rel="noopener">15:55</a>)</li><li><strong>Agent Studio:</strong> There are templates (Signal, plus a cost agent that flags expensive models doing cheap work), or you can build your own agent with skills such as GitHub, a permissions system or DataDog. Agents run in Arize-managed sandboxes or on your own Modal, Daytona or E2B, with Codex, Cursor, Claude Code or OpenCode as the harness. They can run on a schedule or on an alert, e.g. latency above 10 seconds (<a href="https://www.youtube.com/watch?v=UGuNt2_Oz8s&amp;t=990s" target="_blank" rel="noopener">16:30</a>–<a href="https://www.youtube.com/watch?v=UGuNt2_Oz8s&amp;t=1086s" target="_blank" rel="noopener">18:06</a>)</li></ul><div class="sh">From issue to proven fix</div><ul><li><strong>Living fixtures:</strong> Signal keeps one ticket per problem and dedupes them. Failures you add to a dataset grow into a regression fixture that changes with new failure modes; adding them stays manual on purpose so a human judges what is good enough (<a href="https://www.youtube.com/watch?v=UGuNt2_Oz8s&amp;t=1115s" target="_blank" rel="noopener">18:35</a>–<a href="https://www.youtube.com/watch?v=UGuNt2_Oz8s&amp;t=1166s" target="_blank" rel="noopener">19:26</a>)</li><li><strong>Eval menu:</strong> Code checks are cheapest, LLM-as-a-judge handles qualitative cases, and agent-as-a-judge is the most expensive. Decision models, about a month old, are a very cheap way to get typed yes/no, choice or score outputs (repeat) (<a href="https://www.youtube.com/watch?v=UGuNt2_Oz8s&amp;t=1255s" target="_blank" rel="noopener">20:55</a>–<a href="https://www.youtube.com/watch?v=UGuNt2_Oz8s&amp;t=1369s" target="_blank" rel="noopener">22:49</a>)</li><li><strong>One-click eval from an issue:</strong> From Signal&#39;s &quot;redundant search retries&quot; issue, Arize&#39;s Alex agent writes a judge that flags a redundant retry whenever search product is called more than once. Signal also caught an &quot;orphan spans&quot; mistake in his own instrumentation. You can track each eval&#39;s cost and retire it once the check lives in your dev flow (<a href="https://www.youtube.com/watch?v=UGuNt2_Oz8s&amp;t=1500s" target="_blank" rel="noopener">25:00</a>–<a href="https://www.youtube.com/watch?v=UGuNt2_Oz8s&amp;t=1603s" target="_blank" rel="noopener">26:43</a>)</li><li><strong>Experiment proves it:</strong> The agent is rerun with the v2 fix on the failure fixture. A score of 88.9% met his threshold (&quot;ship it&quot;), and three other evals were checked for regressions. You can annotate outputs you disagree with, and gate this in CI/CD if you watch agent and judge costs (<a href="https://www.youtube.com/watch?v=UGuNt2_Oz8s&amp;t=1714s" target="_blank" rel="noopener">28:34</a>–<a href="https://www.youtube.com/watch?v=UGuNt2_Oz8s&amp;t=1829s" target="_blank" rel="noopener">30:29</a>)</li></ul><div class="sh">Humans, cost and Q&amp;A</div><ul><li><strong>Confidence routing:</strong> Decision models return explicit confidence scores, so low-confidence cases can go straight to an annotation queue. In a spam test, 4.6% of cases scored 0.3–0.7 and went to people, and the rest held 99.5% accuracy (<a href="https://www.youtube.com/watch?v=UGuNt2_Oz8s&amp;t=1981s" target="_blank" rel="noopener">33:01</a>–<a href="https://www.youtube.com/watch?v=UGuNt2_Oz8s&amp;t=2040s" target="_blank" rel="noopener">34:00</a>)</li><li><strong>Evaluating qualitative output:</strong> One example only teaches overfitting. For Alex&#39;s &quot;filter with AI&quot; feature they look at the whole session (did the user ask again, how many extra filters they added) plus PM annotations, then tune the judge prompt to run on the lowest-cost model. Run fixture evals in CI on every push and sampled evals on prod, sized by what a 0.1% failure costs (<a href="https://www.youtube.com/watch?v=UGuNt2_Oz8s&amp;t=2515s" target="_blank" rel="noopener">41:55</a>–<a href="https://www.youtube.com/watch?v=UGuNt2_Oz8s&amp;t=2713s" target="_blank" rel="noopener">45:13</a>)</li><li><strong>Signal on Signal, and cost:</strong> They run Signal on its own traces, but past proxies like PR merge rate there&#39;s no ground truth, so returns diminish. On cost, an agent might cost $8 and its improvement loop $20; there&#39;s no fixed budget share, and the levers are how much context and skills you give it and eval sampling (<a href="https://www.youtube.com/watch?v=UGuNt2_Oz8s&amp;t=2803s" target="_blank" rel="noopener">46:43</a>–<a href="https://www.youtube.com/watch?v=UGuNt2_Oz8s&amp;t=2892s" target="_blank" rel="noopener">48:12</a>, <a href="https://www.youtube.com/watch?v=UGuNt2_Oz8s&amp;t=3089s" target="_blank" rel="noopener">51:29</a>–<a href="https://www.youtube.com/watch?v=UGuNt2_Oz8s&amp;t=3127s" target="_blank" rel="noopener">52:07</a>)</li></ul></div></article><article class="it full" id="v-kRJjSOYqW0I" data-title="How to Test Your Agents on Real Tasks With Harbor - Xander Song, Arize AI" data-channel="AI Engineer" data-verdict="worth"><a class="th" href="https://www.youtube.com/watch?v=kRJjSOYqW0I" target="_blank" rel="noopener"><img src="'+r+'" srcset="'+A+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-worth">worth</span><h3><a href="https://www.youtube.com/watch?v=kRJjSOYqW0I" target="_blank" rel="noopener">How to Test Your Agents on Real Tasks With Harbor - Xander Song, Arize AI</a></h3><div class="meta">AI Engineer · Xander Song, engineer on Phoenix, Arize AI · uploaded 27 Oct, 12:30 AM IST · 56:01</div><div class="verdict v-worth"><b>Verdict:</b> worth watching — the first proper Harbor explainer in the history, plus a concrete oracle-backed prompt A/B; the 25:07–33:21 Q&amp;A can be skipped.</div><div class="repeat">🔁 Repeat: &#39;evals for agents&#39; — seen 41 times before. New here: the first full walkthrough of Harbor itself (it was only mentioned in Cisco&#39;s bank-compliance talk): tasks, verifiers, rewards, trials, oracles and jobs.</div><div class="repeat">🔁 Repeat: &#39;agent observability&#39; — seen 23 times before. New here: Harbor&#39;s ATIF trajectories are converted to OpenInference traces so Phoenix can compare two jobs task by task.</div><div class="repeat">🔁 Repeat: &#39;sandboxes for agents&#39; — seen 15 times before. New here: each trial gets its own fresh Docker container, run in parallel on Daytona with about 200 concurrent workers.</div><div class="repeat">🔁 Repeat: &#39;agent skills&#39; — seen 13 times before. New here: happy-path regression tests per skill, and the trade-off of &quot;did the skill fire&quot; tests.</div><div class="repeat">🔁 Repeat: &#39;MCP servers&#39; — seen 33 times before. New here: only as the case study, where a read-only SQL tool was added to Phoenix&#39;s MCP server.</div><div class="sh">How Harbor works</div><ul><li><strong>The idea:</strong> A task is a natural-language instruction. Harbor drops your agent into a fresh sandbox with real data, and per-task verifiers check the side effects it left and emit rewards such as 0/1. Hold tasks and verifiers constant, change the agent, and you get evidence of improvement or regression instead of vibes (<a href="https://www.youtube.com/watch?v=kRJjSOYqW0I&amp;t=88s" target="_blank" rel="noopener">1:28</a>–<a href="https://www.youtube.com/watch?v=kRJjSOYqW0I&amp;t=158s" target="_blank" rel="noopener">2:38</a>)</li><li><strong>Anatomy of a task and job:</strong> Each task has an instruction markdown file, a Dockerfile environment seeded with data (e.g. a SQLite file or a git repo at a commit) and a tests directory of verifier scripts. Each task runs a configurable number of trials, rewards go to a reward.txt file, and optional ATIF (Agent Trajectory Interchange Format) JSON records the agent&#39;s steps. A full run over a dataset is a &quot;job&quot; (<a href="https://www.youtube.com/watch?v=kRJjSOYqW0I&amp;t=232s" target="_blank" rel="noopener">3:52</a>–<a href="https://www.youtube.com/watch?v=kRJjSOYqW0I&amp;t=417s" target="_blank" rel="noopener">6:57</a>)</li><li><strong>Oracles first:</strong> An oracle is a script that solves the task. Running it before any agent shakes out bad data, environments and verifiers &quot;before you spend any money on tokens&quot; (<a href="https://www.youtube.com/watch?v=kRJjSOYqW0I&amp;t=437s" target="_blank" rel="noopener">7:17</a>–<a href="https://www.youtube.com/watch?v=kRJjSOYqW0I&amp;t=463s" target="_blank" rel="noopener">7:43</a>)</li><li><strong>Verifiers as black-box tests:</strong> In the failing-migration example, verifiers rerun the up migration (exit code 0) and check columns and indexes. They are mounted only after the agent finishes so it can&#39;t cheat, and like good integration tests they ignore how the agent worked, which lets you &quot;refactor under green&quot; (<a href="https://www.youtube.com/watch?v=kRJjSOYqW0I&amp;t=494s" target="_blank" rel="noopener">8:14</a>–<a href="https://www.youtube.com/watch?v=kRJjSOYqW0I&amp;t=733s" target="_blank" rel="noopener">12:13</a>)</li><li><strong>Scale and pass@k:</strong> Every trial is independent, so for example Claude Code with Opus 5 and Codex with GPT-5, three trials each, run in parallel; Arize uses Daytona with about 200 concurrent workers and computes pass@k per task and across the dataset (<a href="https://www.youtube.com/watch?v=kRJjSOYqW0I&amp;t=876s" target="_blank" rel="noopener">14:36</a>–<a href="https://www.youtube.com/watch?v=kRJjSOYqW0I&amp;t=952s" target="_blank" rel="noopener">15:52</a>)</li><li><strong>It&#39;s a CLI orchestrator:</strong> Harbor runs on your laptop or a GitHub Actions runner and drives everything through scripts placed in set locations in the image; &quot;did I put my scripts in the right place&quot; is the whole contract. There are no linters for that, so download Harbor&#39;s skills to help your coding agent set it up (<a href="https://www.youtube.com/watch?v=kRJjSOYqW0I&amp;t=1567s" target="_blank" rel="noopener">26:07</a>–<a href="https://www.youtube.com/watch?v=kRJjSOYqW0I&amp;t=1671s" target="_blank" rel="noopener">27:51</a>), (<a href="https://www.youtube.com/watch?v=kRJjSOYqW0I&amp;t=3276s" target="_blank" rel="noopener">54:36</a>–<a href="https://www.youtube.com/watch?v=kRJjSOYqW0I&amp;t=3299s" target="_blank" rel="noopener">54:59</a>)</li></ul><div class="sh">How the Phoenix team uses it</div><ul><li><strong>Phoenix mapping:</strong> Harbor datasets, jobs, trials and rewards map to Phoenix datasets, experiments and evaluations, and ATIF is converted to OpenInference (OTel semantic conventions; Arize recently donated the spec to the cloud-native OTel working group). Harbor has its own local UI and hosted service, so Phoenix is optional (<a href="https://www.youtube.com/watch?v=kRJjSOYqW0I&amp;t=1061s" target="_blank" rel="noopener">17:41</a>–<a href="https://www.youtube.com/watch?v=kRJjSOYqW0I&amp;t=1225s" target="_blank" rel="noopener">20:25</a>)</li><li><strong>Whole app in the container:</strong> Phoenix is a single-node, Grafana-like server, so they put it in Docker with a SQLite file of realistic data and test three surfaces: a coding agent with the CLI, a coding agent with the MCP server, and their server-side agent Pixie. A task like &quot;find hallucinated LLM calls from last week and add them to a dataset&quot; is verified by hitting REST or querying SQLite directly (<a href="https://www.youtube.com/watch?v=kRJjSOYqW0I&amp;t=1263s" target="_blank" rel="noopener">21:03</a>–<a href="https://www.youtube.com/watch?v=kRJjSOYqW0I&amp;t=1458s" target="_blank" rel="noopener">24:18</a>)</li><li><strong>Distributed systems are harder:</strong> With S3 and many services, he suggests carving the agent out behind a stable interface. Mocking S3 calls puts you back &quot;in a world of pain&quot;; Harbor can run multiple Docker images, but he hasn&#39;t had to solve this (<a href="https://www.youtube.com/watch?v=kRJjSOYqW0I&amp;t=1773s" target="_blank" rel="noopener">29:33</a>–<a href="https://www.youtube.com/watch?v=kRJjSOYqW0I&amp;t=1876s" target="_blank" rel="noopener">31:16</a>)</li></ul><div class="sh">Case study: steering agents to a SQL tool</div><ul><li><strong>The problem:</strong> Aggregate questions like &quot;busiest day&quot; or &quot;spend per model&quot; made agents page through REST/GraphQL. They added a read-only SQL tool to the MCP server, but agents didn&#39;t know which tool to pick, so they added a one-line prompt hint: for counts or group-bys, use SQL before GraphQL (<a href="https://www.youtube.com/watch?v=kRJjSOYqW0I&amp;t=2028s" target="_blank" rel="noopener">33:48</a>–<a href="https://www.youtube.com/watch?v=kRJjSOYqW0I&amp;t=2149s" target="_blank" rel="noopener">35:49</a>)</li><li><strong>Synthetic tasks with oracle answers:</strong> Claude brainstormed aggregate and non-aggregate user queries across Phoenix&#39;s domains and wrote an oracle solution (a REST call or DB query) for each. He spot-checked the questions and trusts the verifiers (a mix of LLM-as-a-judge and SQL/REST checks) because they pass against the oracles (<a href="https://www.youtube.com/watch?v=kRJjSOYqW0I&amp;t=2197s" target="_blank" rel="noopener">36:37</a>–<a href="https://www.youtube.com/watch?v=kRJjSOYqW0I&amp;t=2241s" target="_blank" rel="noopener">37:21</a>)</li><li><strong>Result:</strong> The agent used SQL more aggressively and average tool calls dropped, while reward stayed flat because answers were already correct, making it an optimization, not a fix. The small dataset understates the gain. Comparing Opus 5 before and after task by task shows GraphQL calls down, SQL up and fewer turns. A live natural-language filter using an in-browser local model failed (<a href="https://www.youtube.com/watch?v=kRJjSOYqW0I&amp;t=2269s" target="_blank" rel="noopener">37:49</a>–<a href="https://www.youtube.com/watch?v=kRJjSOYqW0I&amp;t=2306s" target="_blank" rel="noopener">38:26</a>), (<a href="https://www.youtube.com/watch?v=kRJjSOYqW0I&amp;t=2671s" target="_blank" rel="noopener">44:31</a>–<a href="https://www.youtube.com/watch?v=kRJjSOYqW0I&amp;t=2794s" target="_blank" rel="noopener">46:34</a>)</li><li><strong>Peeking at trajectories is &quot;cheating&quot;:</strong> Checking whether the agent used SQL breaks the black-box rule. He says that&#39;s fine when optimizing a metric, while correctness regression tests keep pure side-effect verifiers (<a href="https://www.youtube.com/watch?v=kRJjSOYqW0I&amp;t=2514s" target="_blank" rel="noopener">41:54</a>)</li></ul><div class="sh">Regression tests and skills</div><ul><li><strong>Skills as end-to-end tests:</strong> They&#39;re nailing down happy paths for their most important skills across models and providers, like Playwright with an LLM in the loop. &quot;Did the right skill fire&quot; tests are easy to write but flaky when skill names or front matter change (<a href="https://www.youtube.com/watch?v=kRJjSOYqW0I&amp;t=2915s" target="_blank" rel="noopener">48:35</a>–<a href="https://www.youtube.com/watch?v=kRJjSOYqW0I&amp;t=3042s" target="_blank" rel="noopener">50:42</a>)</li><li><strong>The unit under test:</strong> It&#39;s not Claude Code alone but the hybrid of Claude Code plus their MCP server, skills, CLI and APIs, which is why all of it goes into one environment. Getting realistic data is &quot;the hard part&quot; (<a href="https://www.youtube.com/watch?v=kRJjSOYqW0I&amp;t=3172s" target="_blank" rel="noopener">52:52</a>–<a href="https://www.youtube.com/watch?v=kRJjSOYqW0I&amp;t=3338s" target="_blank" rel="noopener">55:38</a>)</li></ul></div></article><article class="it full" id="v-4UtrRVtUN_g" data-title="How to Build an AI Code Review Agent - Daksh Gupta, Greptile" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=4UtrRVtUN_g" target="_blank" rel="noopener"><img src="'+i+'" srcset="'+I+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=4UtrRVtUN_g" target="_blank" rel="noopener">How to Build an AI Code Review Agent - Daksh Gupta, Greptile</a></h3><div class="meta">AI Engineer · Daksh Gupta, co-founder, Greptile · uploaded 26 Oct, 2:30 PM IST · 18:27</div><div class="verdict v-skim"><b>Verdict:</b> skim from 6:02 — the first six minutes restate the well-covered review bottleneck; the six fixes after that (especially model inversion and model routing) are concrete and new.</div><div class="repeat">🔁 Repeat: &#39;AI-generated code validation&#39; — seen 23 times before (incl. his own &quot;AI-Generated Code Is Already Competing With Human Code&quot;). New here: a concrete build recipe for your own review agent, with numbers on cost, model inversion and model routing.</div><div class="repeat">🔁 Repeat: &#39;sandboxes for agents&#39; — seen 15 times before. New here: sandboxes used for end-to-end QA of a PR branch with vision models, not just for running the agent.</div><div class="repeat">🔁 Repeat: &#39;token costs / AI spend&#39; — seen 9 times before. New here: $3–25 per PR for naive agent review, and a ~20% frontier / 80% small-model split to cut it.</div><div class="sh">The naive version and why it breaks</div><ul><li><strong>Sandbox + agent + webhook:</strong> Put Codex or Claude Code (he recommends model-independent open-source harnesses like OpenCode or Pi) in a sandbox such as Firecracker, have a GitHub/GitLab PR webhook send it the diff, and post feedback back through GitHub&#39;s review APIs; you get comments in about 5 minutes (<a href="https://www.youtube.com/watch?v=4UtrRVtUN_g&amp;t=184s" target="_blank" rel="noopener">3:04</a>–<a href="https://www.youtube.com/watch?v=4UtrRVtUN_g&amp;t=234s" target="_blank" rel="noopener">3:54</a>)</li><li><strong>What goes wrong:</strong> It misses bugs and codebase context, costs $3 to $25 per pull request in tokens, and floods PRs with nitpicks that coding agents then dutifully &quot;fix&quot; into painfully defensive code; re-running it on the same PR keeps finding new issues (<a href="https://www.youtube.com/watch?v=4UtrRVtUN_g&amp;t=240s" target="_blank" rel="noopener">4:00</a>–<a href="https://www.youtube.com/watch?v=4UtrRVtUN_g&amp;t=360s" target="_blank" rel="noopener">6:00</a>)</li></ul><div class="sh">Fixes: prompts, data, model inversion</div><ul><li><strong>Targeted prompts, no nitpicks:</strong> Mine your past outages for the bug types you most often produce, have the prompt hunt for those, and define nitpicks explicitly so it skips them. Small prompt changes swing the comment count a lot, and since only about 1 in 1,000 PRs has a catastrophic bug you can&#39;t tell what you&#39;re now missing (<a href="https://www.youtube.com/watch?v=4UtrRVtUN_g&amp;t=363s" target="_blank" rel="noopener">6:03</a>–<a href="https://www.youtube.com/watch?v=4UtrRVtUN_g&amp;t=462s" target="_blank" rel="noopener">7:42</a>)</li><li><strong>Dataset of incident PRs:</strong> Replay every PR that caused an outage through each new agent version to measure catch rate. About 80–90% of bugs repeat old mistakes, but agents increasingly fail in novel ways, so the set has to keep updating (<a href="https://www.youtube.com/watch?v=4UtrRVtUN_g&amp;t=464s" target="_blank" rel="noopener">7:44</a>–<a href="https://www.youtube.com/watch?v=4UtrRVtUN_g&amp;t=540s" target="_blank" rel="noopener">9:00</a>)</li><li><strong>Model inversion:</strong> Claude models make about 3x more &quot;one-off&quot; errors than GPT models, while GPT models produce more auth bypasses, so review Claude-written code with GPT and vice versa. Detect the author from fingerprints (Codex&#39;s `codex/` branch names, Claude&#39;s &quot;Co-authored by Claude&quot;), which works about 80% of the time; flipping models gave a 10% higher catch rate (<a href="https://www.youtube.com/watch?v=4UtrRVtUN_g&amp;t=542s" target="_blank" rel="noopener">9:02</a>–<a href="https://www.youtube.com/watch?v=4UtrRVtUN_g&amp;t=660s" target="_blank" rel="noopener">11:00</a>)</li></ul><div class="sh">Context, testing and cost</div><ul><li><strong>Codebase context beyond grep:</strong> He argues grep is imprecise and expensive (most coding-agent tokens are grep, file read, cache write). Greptile builds an index cataloging each part of the codebase (e.g. auth flows, diagrams, every involved file), which is what lets it catch things like auth bypasses (<a href="https://www.youtube.com/watch?v=4UtrRVtUN_g&amp;t=664s" target="_blank" rel="noopener">11:04</a>–<a href="https://www.youtube.com/watch?v=4UtrRVtUN_g&amp;t=753s" target="_blank" rel="noopener">12:33</a>)</li><li><strong>Docs, tickets and a living wiki:</strong> Correct code can still miss the author&#39;s intent (e.g. one-line Slack requests). Feeding Jira/Linear tickets and Confluence/Notion docs helps a lot; Greptile merges these plus production telemetry and logs into a &quot;living wiki&quot; world model so the agent never reads a file it doesn&#39;t need (<a href="https://www.youtube.com/watch?v=4UtrRVtUN_g&amp;t=756s" target="_blank" rel="noopener">12:36</a>–<a href="https://www.youtube.com/watch?v=4UtrRVtUN_g&amp;t=863s" target="_blank" rel="noopener">14:23</a>)</li><li><strong>Autonomous testing with computer use:</strong> Spin the stack up in a dependency-rich sandbox on the PR branch and let vision models click through documented flows to catch things like a button hidden on iPhone; he calls end-to-end QA &quot;nearly solved&quot; with the newest GPT and Opus models, but you need a simple build script and a flow map (<a href="https://www.youtube.com/watch?v=4UtrRVtUN_g&amp;t=866s" target="_blank" rel="noopener">14:26</a>–<a href="https://www.youtube.com/watch?v=4UtrRVtUN_g&amp;t=961s" target="_blank" rel="noopener">16:01</a>)</li><li><strong>Cheaper models for most subtasks:</strong> Greptile uses frontier models for about 20% (bug analysis, review), smaller models for the long tail of exploration and file reads, and a lightweight computer-use model for flows, across about 20 subtasks; simple swaps get you 70–80% of the savings, but without a good dataset you won&#39;t notice the drop in catch rate (<a href="https://www.youtube.com/watch?v=4UtrRVtUN_g&amp;t=965s" target="_blank" rel="noopener">16:05</a>–<a href="https://www.youtube.com/watch?v=4UtrRVtUN_g&amp;t=1077s" target="_blank" rel="noopener">17:57</a>)</li></ul></div></article><article class="it full" id="v-Y_p3y6zP5QE" data-title="Build Your Own Team of Managed Agents - Jack Wotherspoon, Google DeepMind" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=Y_p3y6zP5QE" target="_blank" rel="noopener"><img src="'+l+'" srcset="'+x+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=Y_p3y6zP5QE" target="_blank" rel="noopener">Build Your Own Team of Managed Agents - Jack Wotherspoon, Google DeepMind</a></h3><div class="meta">AI Engineer · Jack Wotherspoon, developer experience engineer, Google DeepMind · uploaded 26 Oct, 1:30 PM IST · 19:44</div><div class="verdict v-skim"><b>Verdict:</b> skim from 7:02 — mostly the same managed-agent pattern Anthropic&#39;s series already covered; the Gemini-specific parts worth seeing are Argon&#39;s long decode and shared environment IDs (7:02–12:18).</div><div class="repeat">🔁 Repeat: &#39;Claude Managed Agents&#39; — seen 5 times before (Anthropic&#39;s four-part series and the Flows talk cover the same idea: hosted sandbox, harness, secrets proxy, scheduled runs, multi-agent SEC/stock research demos). New here: Google&#39;s version in the Gemini API, with shareable environment IDs and the Gemini 4 Argon model.</div><div class="repeat">🔁 Repeat: &#39;sandboxes for agents&#39; — seen 15 times before. New here: the sandbox&#39;s file system is its own &quot;environment&quot; object that several agents can reuse.</div><div class="repeat">🔁 Repeat: &#39;multi-agent / A2A&#39; — seen 14 times before. New here: little; agents hand off through shared files in one environment.</div><div class="repeat">🔁 Repeat: &#39;always-on agents&#39; — seen 7 times before. New here: scheduled triggers with webhooks, e.g. a pre-market run at 8:30 AM.</div><div class="repeat">🔁 Repeat: &#39;secrets management&#39; — seen 6 times before. New here: little; same proxy-injects-the-token pattern as Anthropic&#39;s.</div><div class="sh">What Gemini Managed Agents are</div><ul><li><strong>Why cloud agents:</strong> Running coding agents in a cloud sandbox lets them write and run tests and verify results without hijacking your laptop&#39;s browser, and lets you share a customized agent with colleagues or ship it in an app instead of tying it to your own subscription (repeat) (<a href="https://www.youtube.com/watch?v=Y_p3y6zP5QE&amp;t=54s" target="_blank" rel="noopener">0:54</a>–<a href="https://www.youtube.com/watch?v=Y_p3y6zP5QE&amp;t=118s" target="_blank" rel="noopener">1:58</a>)</li><li><strong>One API call:</strong> Instead of building a VM, a harness and firewall rules yourself, you call the Interactions API (GA earlier this year) with the base Antigravity agent and `environment = remote`; the sandbox runs on Google Cloud with built-in Google Search, file and code-execution tools plus custom functions and MCP tools (<a href="https://www.youtube.com/watch?v=Y_p3y6zP5QE&amp;t=132s" target="_blank" rel="noopener">2:12</a>–<a href="https://www.youtube.com/watch?v=Y_p3y6zP5QE&amp;t=318s" target="_blank" rel="noopener">5:18</a>)</li><li><strong>Building blocks:</strong> The same Antigravity harness used in Google&#39;s Antigravity products, an environment, uploadable skills and AGENTS.md files, new credentials injection (tokens or MCP OAuth) and triggers that wake an agent on a schedule and can fire webhooks, e.g. to Slack (repeat) (<a href="https://www.youtube.com/watch?v=Y_p3y6zP5QE&amp;t=322s" target="_blank" rel="noopener">5:22</a>–<a href="https://www.youtube.com/watch?v=Y_p3y6zP5QE&amp;t=419s" target="_blank" rel="noopener">6:59</a>)</li></ul><div class="sh">Models and primitives</div><ul><li><strong>Gemini 4 Argon and long decode:</strong> You set the model with one config line, e.g. Gemini Flash for fast work or Gemini 4 Argon, launched the day before and pitched as strong on financial tasks and multi-document analysis. Its &quot;long decode&quot; lets the 1M-token limit be shared between input, thinking and output instead of the usual ~64K output cap (<a href="https://www.youtube.com/watch?v=Y_p3y6zP5QE&amp;t=422s" target="_blank" rel="noopener">7:02</a>–<a href="https://www.youtube.com/watch?v=Y_p3y6zP5QE&amp;t=525s" target="_blank" rel="noopener">8:45</a>)</li><li><strong>Interactions vs environments:</strong> Interactions hold the conversation (pass one interaction&#39;s ID to the next for a second turn); environments hold the sandbox file system. Passing an environment ID to a new agent gives it a fresh context window over the same files, and you can save a refined agent with `agents.create` and call it by ID (<a href="https://www.youtube.com/watch?v=Y_p3y6zP5QE&amp;t=530s" target="_blank" rel="noopener">8:50</a>–<a href="https://www.youtube.com/watch?v=Y_p3y6zP5QE&amp;t=738s" target="_blank" rel="noopener">12:18</a>)</li><li><strong>Secrets stay out:</strong> A proxy puts a dummy token in the sandbox and swaps in the real GitHub token only when the call reaches the GitHub API, so the agent can never read it (repeat) (<a href="https://www.youtube.com/watch?v=Y_p3y6zP5QE&amp;t=741s" target="_blank" rel="noopener">12:21</a>–<a href="https://www.youtube.com/watch?v=Y_p3y6zP5QE&amp;t=789s" target="_blank" rel="noopener">13:09</a>)</li></ul><div class="sh">Demos</div><ul><li><strong>SEC researcher → quant → report:</strong> An SEC filing agent researches Nvidia and writes `metrics.json`; a quant agent reusing the same environment runs Python on it to forecast the share price, and a third agent turns it into a report, with step traces for each tool call (repeat) (<a href="https://www.youtube.com/watch?v=Y_p3y6zP5QE&amp;t=872s" target="_blank" rel="noopener">14:32</a>–<a href="https://www.youtube.com/watch?v=Y_p3y6zP5QE&amp;t=989s" target="_blank" rel="noopener">16:29</a>)</li><li><strong>Inside an app:</strong> A managed agent reads receipts from Google Drive and builds an interactive visualization using a skill, and an AI Studio gallery app runs several ticker agents on VOO to produce a PDF report with charts and links to the Vanguard sources it read (<a href="https://www.youtube.com/watch?v=Y_p3y6zP5QE&amp;t=994s" target="_blank" rel="noopener">16:34</a>–<a href="https://www.youtube.com/watch?v=Y_p3y6zP5QE&amp;t=1169s" target="_blank" rel="noopener">19:29</a>)</li></ul></div></article><article class="it full" id="v-OmyqelTwpOo" data-title="How to Build Voice Agents That Don&#39;t Fall Apart When You Interrupt - Jesse Hall, LiveKit" data-channel="AI Engineer" data-verdict="skip"><a class="th" href="https://www.youtube.com/watch?v=OmyqelTwpOo" target="_blank" rel="noopener"><img src="'+h+'" srcset="'+S+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skip">skip</span><h3><a href="https://www.youtube.com/watch?v=OmyqelTwpOo" target="_blank" rel="noopener">How to Build Voice Agents That Don&#39;t Fall Apart When You Interrupt - Jesse Hall, LiveKit</a></h3><div class="meta">AI Engineer · Jesse Hall, LiveKit · uploaded 26 Oct, 12:30 PM IST · 20:55</div><div class="verdict v-skip"><b>Verdict:</b> skip — a near-rerun of his 11 Oct LiveKit talk; only the finance framing and the checklist at <a href="https://www.youtube.com/watch?v=OmyqelTwpOo&amp;t=1175s" target="_blank" rel="noopener">19:35</a> are new.</div><div class="repeat">🔁 Repeat: &#39;evals for agents&#39; — seen 41 times before. This is also largely the same talk as Jesse Hall&#39;s 11 Oct &quot;Latency Is a Budget. Humanlike Is the Goal.&quot; (&#39;voice agents&#39;, seen 2 times): same async tools, 9.9% vs 4.5% turn-detection figures and Gemma 4 31B result. New here: it&#39;s pitched at financial services (mis-heard payment dates, confirming amounts, verifying identity) and ends with a pre-launch checklist.</div><div class="sh">Why leaderboards don&#39;t pick your voice stack</div><ul><li><strong>Cascaded vs speech-to-speech:</strong> Most voice agents still chain three models (speech-to-text, LLM, text-to-speech). Speech-to-speech models can replace that chain, but he says they&#39;re &quot;not quite there for every use case yet&quot; (<a href="https://www.youtube.com/watch?v=OmyqelTwpOo&amp;t=261s" target="_blank" rel="noopener">4:21</a>–<a href="https://www.youtube.com/watch?v=OmyqelTwpOo&amp;t=298s" target="_blank" rel="noopener">4:58</a>)</li><li><strong>Errors flow downhill:</strong> Leaderboards score each model on its own, but you ship a whole conversation. If a caller says &quot;pay on the 3rd&quot; and speech-to-text hears &quot;the 30th&quot;, the LLM plans for the 30th without knowing it&#39;s wrong. Leaderboards also test on clean audio, not callers on speakerphone in traffic (<a href="https://www.youtube.com/watch?v=OmyqelTwpOo&amp;t=305s" target="_blank" rel="noopener">5:05</a>–<a href="https://www.youtube.com/watch?v=OmyqelTwpOo&amp;t=377s" target="_blank" rel="noopener">6:17</a>)</li><li><strong>Time to first audio and first sentence:</strong> A TTS dashboard may show 210 ms time to first byte, yet LiveKit found popular providers sending up to 3/4 of a second of silence after that byte. For LLMs, TTS needs a whole sentence before it can speak, so measure time to first sentence, not first token (repeat) (<a href="https://www.youtube.com/watch?v=OmyqelTwpOo&amp;t=406s" target="_blank" rel="noopener">6:46</a>–<a href="https://www.youtube.com/watch?v=OmyqelTwpOo&amp;t=510s" target="_blank" rel="noopener">8:30</a>)</li></ul><div class="sh">Keeping the conversation human</div><ul><li><strong>Async tool calls:</strong> Back-end lookups like checking a payment or filing a dispute can take up to 40 seconds. Like a person saying &quot;give me a second&quot;, the agent should keep talking or ask the next question; one async/await change in the tool call lets the conversation and the tool run separately (repeat) (<a href="https://www.youtube.com/watch?v=OmyqelTwpOo&amp;t=512s" target="_blank" rel="noopener">8:32</a>–<a href="https://www.youtube.com/watch?v=OmyqelTwpOo&amp;t=611s" target="_blank" rel="noopener">10:11</a>)</li><li><strong>Hotel booking demo:</strong> A Gilded Rose Hotel receptionist reads back dates, name, email and phone number, keeps going when interrupted, and saves each field to a real back end without waiting for confirmation. It corrects itself if a tool call fails and hands off to a human as a last resort (<a href="https://www.youtube.com/watch?v=OmyqelTwpOo&amp;t=614s" target="_blank" rel="noopener">10:14</a>–<a href="https://www.youtube.com/watch?v=OmyqelTwpOo&amp;t=750s" target="_blank" rel="noopener">12:30</a>)</li><li><strong>Audio-aware turn detection:</strong> LiveKit&#39;s turn detector listens to rhythm, pitch and intonation as well as the transcript. It cuts users off 4.5% of the time versus 9.9% for the leading alternative on their use cases, so &quot;500… and $55.23&quot; isn&#39;t cut off at &quot;500&quot;. The evals are open source (repeat) (<a href="https://www.youtube.com/watch?v=OmyqelTwpOo&amp;t=753s" target="_blank" rel="noopener">12:33</a>–<a href="https://www.youtube.com/watch?v=OmyqelTwpOo&amp;t=839s" target="_blank" rel="noopener">13:59</a>)</li><li><strong>The latency budget:</strong> The gap between the caller&#39;s last syllable and the agent&#39;s first sound has to hold every model and handoff. Around 1.5 seconds the call still holds but feels a little off; 500–600 ms feels human (repeat) (<a href="https://www.youtube.com/watch?v=OmyqelTwpOo&amp;t=842s" target="_blank" rel="noopener">14:02</a>–<a href="https://www.youtube.com/watch?v=OmyqelTwpOo&amp;t=923s" target="_blank" rel="noopener">15:23</a>)</li></ul><div class="sh">Benchmark your own stack</div><ul><li><strong>Simulated callers:</strong> Run a working agent against simulated callers who change their minds, interrupt, mumble or have background noise, in text mode (business logic) or audio mode (the full pipeline). Score the outcome, e.g. did the right reservation or charge land in the database, and also the steps taken (extra steps, hallucinated function calls). Then swap models on identical input to build a benchmark for your own agent. On the hotel agent, Gemma 4 31B on LiveKit inference ranked top, and the same model on another provider was slower (repeat) (<a href="https://www.youtube.com/watch?v=OmyqelTwpOo&amp;t=944s" target="_blank" rel="noopener">15:44</a>–<a href="https://www.youtube.com/watch?v=OmyqelTwpOo&amp;t=1146s" target="_blank" rel="noopener">19:06</a>)</li><li><strong>Pre-launch checklist:</strong> Set the latency budget the caller hears, measure time to first audio and first sentence, confirm critical dates and money amounts, verify identity before opening an account, keep listening while slow tools run, and turn every failure found in simulation into a regression scenario (<a href="https://www.youtube.com/watch?v=OmyqelTwpOo&amp;t=1175s" target="_blank" rel="noopener">19:35</a>–<a href="https://www.youtube.com/watch?v=OmyqelTwpOo&amp;t=1213s" target="_blank" rel="noopener">20:13</a>)</li></ul></div></article><article class="it full" id="v-wbRaBUhkVhc" data-title="The Silicon Valley Intro Was Secretly a Great Index Fund (Except Theranos)" data-channel="Better Stack" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=wbRaBUhkVhc" target="_blank" rel="noopener"><img src="'+c+'" srcset="'+R+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">Better Stack</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=wbRaBUhkVhc" target="_blank" rel="noopener">The Silicon Valley Intro Was Secretly a Great Index Fund (Except Theranos)</a></h3><div class="meta">Better Stack · speaker not named · uploaded 26 Oct, 9:15 AM IST · 6:55</div><div class="verdict v-skim"><b>Verdict:</b> skim — a fun 7-minute data piece with no AI or dev content; the market-cap ETF result at <a href="https://www.youtube.com/watch?v=wbRaBUhkVhc&amp;t=281s" target="_blank" rel="noopener">4:41</a> is the punchline.</div><div class="sh">Building the fund</div><ul><li><strong>Tagging the logos:</strong> HBO&#39;s <em>Silicon Valley</em> intro (studio yU+co) was updated each season, adding new startups, bulldozing dead ones and parking FBI vans outside Theranos. Going frame by frame through eight versions, including a rare season 1 cut with the Adobe logo, he found 65 logos, or about 41 companies you could actually own (<a href="https://www.youtube.com/watch?v=wbRaBUhkVhc&amp;t=27s" target="_blank" rel="noopener">0:27</a>–<a href="https://www.youtube.com/watch?v=wbRaBUhkVhc&amp;t=81s" target="_blank" rel="noopener">1:21</a>)</li><li><strong>Fund 1, the thought experiment:</strong> $1,000 into each company the day after its season premiere, buying startups at their latest funding-round price and never selling. $41,000 became $69,448 (+69%) by the Dec 2019 finale, versus +58% for the S&amp;P 500 (<a href="https://www.youtube.com/watch?v=wbRaBUhkVhc&amp;t=83s" target="_blank" rel="noopener">1:23</a>–<a href="https://www.youtube.com/watch?v=wbRaBUhkVhc&amp;t=114s" target="_blank" rel="noopener">1:54</a>)</li><li><strong>Coinbase and Reddit carry it:</strong> Coinbase got a tower in season 5 at $8.25 a share and closed its first trading day in Apr 2021 at $328, lifting the whole fund 26% in one day. The fund peaked at $223,964 on 19 Sep 2025, mostly from Coinbase ($41,491) and Reddit, bought in season 4 at $6.26 and now worth $42,249. Today it&#39;s $181,583 (4.4x), beating the S&amp;P 500 (4.2x) but not the Nasdaq-100 (6.9x) (<a href="https://www.youtube.com/watch?v=wbRaBUhkVhc&amp;t=116s" target="_blank" rel="noopener">1:56</a>–<a href="https://www.youtube.com/watch?v=wbRaBUhkVhc&amp;t=186s" target="_blank" rel="noopener">3:06</a>)</li></ul><div class="sh">Making it realistic</div><ul><li><strong>Fund 2, a regular brokerage account:</strong> Startups are bought only on their first public trading day (Uber 2019, Airbnb 2020, Coinbase 2021, Reddit 2024), so Theranos is never bought. About 32 companies, $32,000 in, is now about $126,000, versus about $124,000 in the S&amp;P 500 and almost $200,000 in the Nasdaq-100 (<a href="https://www.youtube.com/watch?v=wbRaBUhkVhc&amp;t=186s" target="_blank" rel="noopener">3:06</a>–<a href="https://www.youtube.com/watch?v=wbRaBUhkVhc&amp;t=257s" target="_blank" rel="noopener">4:17</a>)</li><li><strong>Equal weight is the problem:</strong> The picks were good (Apple, Google, Facebook, Amazon, Tesla), but equal weighting counted Theranos the same as Apple. Apple turned $1,000 into $21,346, &quot;and Theranos turned its $1,000 into prison&quot; (<a href="https://www.youtube.com/watch?v=wbRaBUhkVhc&amp;t=259s" target="_blank" rel="noopener">4:19</a>–<a href="https://www.youtube.com/watch?v=wbRaBUhkVhc&amp;t=279s" target="_blank" rel="noopener">4:39</a>)</li><li><strong>Fund 3, a market-cap ETF:</strong> $10,000 invested once in Apr 2014, rebalanced each premiere and weighted by market cap (Apple about 30% and Google 24% in 2014). It&#39;s now $113,987 (over 11x), versus 5.1x for the S&amp;P 500 and 9.1x for the Nasdaq-100, the only one of seven versions to beat both. By the last rebalance, Apple, Microsoft and Alphabet were 58% of it: &quot;a big tech fund that happens to own a bit of Yelp&quot; (<a href="https://www.youtube.com/watch?v=wbRaBUhkVhc&amp;t=281s" target="_blank" rel="noopener">4:41</a>–<a href="https://www.youtube.com/watch?v=wbRaBUhkVhc&amp;t=350s" target="_blank" rel="noopener">5:50</a>)</li><li><strong>The other four versions:</strong> Equal-weight ETF about 6.4x, startups-only pretend VC fund 3.6x, season-1 companies held forever about 5.4x, and selling everything after the finale did slightly worse than holding. Companies on screen were worth about $1.6T at season 1, $6.4T at the finale and $21.1T today. Nvidia, worth $10B at the pilot and $5T now, never made the credits; $1,000 in it then would be $490,000 (<a href="https://www.youtube.com/watch?v=wbRaBUhkVhc&amp;t=350s" target="_blank" rel="noopener">5:50</a>–<a href="https://www.youtube.com/watch?v=wbRaBUhkVhc&amp;t=398s" target="_blank" rel="noopener">6:38</a>)</li></ul></div></article></div>',1))])}const E=u(q,[["render",U]]);export{V as __pageData,E as default};
